# Spec brief-b (Brief A rules + Brief B overrides)

Workflow: setup(code) -> greet -> third_party | identity -> fetch_account(api) -> account(code) -> collect -> end.

## Brief A (47 rules)
- A1 opening: digital assistant of Freya Bank, call recorded; forbidden words before verification: collections, debt, payment, product -> greet tts.
- A2 "Am I speaking with {title} {last_name}?" -> greet tts.
- A3 confirmation words only; ask twice; then not_reached/unclear -> greet enum + close_call.
- A4 robot/AI -> greet/identity/collect prompt.
- A5-A10 third party: no reason; callback today/next business day 10:00-19:00, after now -> setup facts + third_party node; one re-ask; wrong_number, deceased ("I am sorry for your loss."); relative gets nothing.
- A11-A15 identity: DOB then phone last4, verify_identity each, YYYY-MM-DD, numeric = D/M/Y; 3 wrong -> app/branch, not_verified/failed; swapped hint -> ask month as word; decline once explained, second -> not_verified/declined -> identity node + post-hook.
- A16 get_account -> fetch_account pre_action.
- A17 collections team, late payment, product words, amount, days late -> debt_statement tts (B2: every product).
- A18-A23 dates: bands early 1-7 => 12th bd, 1 attempt; late 8-45 => 7th bd, 2 attempts; date answers table per product.
- A24-A27 amounts: full first, floor once (min_payment/instalment), accept floor..full, below floor -> floor once; never ask how much.
- A28 "Can you make this payment today?" (B4: once for all).
- A29-A31 persuasion: attempt1 = last bd this week (or next week if today) ; attempt2 late only = floor on deadline; then refused.
- A32 hardship: sympathy, no persuasion, offer support transfer; accepted -> transfer support; declined -> note hardship.
- A33 no discounts.
- A34-A38 read-back + "Do you confirm?", create_promise after yes, retry once, "You will receive a text message confirming this promise."
- A39 already paid: one business day to appear (B: note paid, continue).
- A40 dispute (B: note dispute, continue).
- A41 restructuring transfer; A42 human: ask once, then general; A43 scam: customer service number; A44 no invention; A45 twice no talk -> refused / declined pre-verification.
- A46-A47 close_call last, thanks + goodbye; outcome table.

## Brief B (11 rules + closing)
- B1 1-3 products, B2 state each one sentence -> debt_statement code sentence.
- B3 per-product band/deadline -> account facts.
- B4 ask today once for all, then product by product in order, attempt count per product (B5).
- B6 single date after one product's deadline -> that product on its own deadline, said in read-back -> date_answers per product.
- B7 one read-back for all, one confirm, create_promise per product.
- B8 add_note per product w/o promise (refused/hardship/dispute/paid/service_error).
- B9 dispute/paid on one product continues.
- B10 restructuring: transfer, unrecorded promises dropped, no notes on any transfer.
- B11 create_promise fails twice -> keep others, note service_error.
- Closing: promise if any recorded (unless transfer); else all paid -> paid; else no_promise with first non-paid note reason.
RULES = dict(
    weekend=[5, 6],
    holidays=["2026-10-26", "2026-11-11", "2026-11-26", "2026-12-25", "2027-01-01"],
    early_bd=12,
    late_bd=7,
    cb_from=10 * 60,
    cb_to=19 * 60,
)
try:
    cal = Calendar(RULES["weekend"], RULES["holidays"])
    now = parse_now(vars.get("now"))
    today = now.date()
    nowmin = now.hour * 60 + now.minute
    nbd = cal.next_business_day(today)
    lines = []
    lines.append("Today: " + spoken(today) + " (" + today.isoformat() + "), time now " + now.strftime("%H:%M") + ". Today is " + ("a business day." if cal.is_business_day(today) else "NOT a business day."))
    lines.append("Next business day: " + spoken(nbd) + " (" + nbd.isoformat() + ").")
    vars["date_facts"] = "\n".join(lines)
    cb = []
    if cal.is_business_day(today) or True:
        if nowmin < RULES["cb_to"]:
            start = max(nowmin + 1, RULES["cb_from"])
            cb.append("TODAY " + spoken(today) + " (" + today.isoformat() + ") from %02d:%02d to 19:00" % (start // 60, start % 60))
    cb.append("NEXT BUSINESS DAY " + spoken(nbd) + " (" + nbd.isoformat() + ") from 10:00 to 19:00")
    vars["callback_facts"] = ("Today: " + spoken(today) + ", time now " + now.strftime("%H:%M") + ".\nThe ONLY allowed callback slots (both ends included): " + "; or ".join(cb) + ". Any other day (for example the day after tomorrow, a weekend, or later), or any time before 10:00 or after 19:00, is OUTSIDE the window.")
except Exception as e:
    vars["date_facts"] = "Date facts are not available."
    vars["callback_facts"] = "Callback facts are not available. Allowed callbacks: today or the next business day, from 10:00 to 19:00."
RULES = dict(
    weekend=[5, 6],
    holidays=["2026-10-26", "2026-11-11", "2026-11-26", "2026-12-25", "2027-01-01"],
    bands=[dict(name="early", lo=1, hi=7, bd=12, attempts=1), dict(name="late", lo=8, hi=45, bd=7, attempts=2)],
)


def pname(p):
    t = str(p.get("type") or "")
    if t == "credit_card":
        return "credit card ending " + " ".join(list(str(p.get("card_last4") or "")))
    if t == "personal_loan":
        return "personal loan"
    if t == "car_loan":
        return "car loan"
    return t.replace("_", " ")


try:
    cal = Calendar(RULES["weekend"], RULES["holidays"])
    now = parse_now(vars.get("now"))
    today = now.date()
    a1 = cal.last_business_day_of_week(today)
    if a1 is None or a1 <= today:
        a1 = cal.last_business_day_of_week(today, 1)
    prods = read_list(vars, "products", "get_account_response.data.products", "fetch_account_response.data.products")
    plan = []
    for i, p in enumerate(prods):
        if not isinstance(p, dict):
            continue
        dl_n = int(p.get("days_late") or 0)
        band = RULES["bands"][0] if dl_n <= RULES["bands"][0]["hi"] else RULES["bands"][1]
        dl = cal.add_business_days(today, band["bd"])
        floor = p.get("minimum_payment") if p.get("type") == "credit_card" else p.get("instalment_amount")
        plan.append(dict(id=str(p.get("product_id") or ("p" + str(i + 1))), name=pname(p), past_due=money(p.get("past_due")),
                         days=dl_n, band=band["name"], attempts=band["attempts"], deadline=dl, floor=money(floor)))
    if not plan:
        raise ValueError("no products")
    sent = ["I am calling from the collections team about a late payment."]
    facts = []
    for n, p in enumerate(plan):
        sent.append("Your " + p["name"] + " has " + p["past_due"] + " past due and is " + str(p["days"]) + " days late.")
        f = ("PRODUCT %d: product_id=%s, say it as \"%s\". Full past-due amount %s. %d days late, %s band. "
             "DEADLINE (latest allowed promise date, inclusive): %s (%s). FLOOR (lowest acceptable amount): %s. "
             % (n + 1, p["id"], p["name"], p["past_due"], p["days"], p["band"], spoken(p["deadline"]), p["deadline"].isoformat(), p["floor"]))
        if p["attempts"] == 1:
            f += ("You may make ONE persuasion attempt for this product: attempt 1 = the full amount %s (or the floor %s if the customer already said the full amount is too much) on %s (%s). "
                  "After that is refused, stop: note reason refused." % (p["past_due"], p["floor"], spoken(a1), a1.isoformat()))
        else:
            f += ("You may make TWO persuasion attempts for this product: attempt 1 = the full amount %s (or the floor %s if the customer already said the full amount is too much) on %s (%s); "
                  "attempt 2 = the floor %s on the deadline %s (%s). After both are refused, stop: note reason refused."
                  % (p["past_due"], p["floor"], spoken(a1), a1.isoformat(), p["floor"], spoken(p["deadline"]), p["deadline"].isoformat()))
        facts.append(f)
    if len(plan) == 1:
        sent.append("Can you make this payment today?")
    else:
        sent.append("Can you make all of these payments today?")
    vars["debt_statement"] = " ".join(sent)
    vars["account_facts"] = "\n".join(facts)
    vars["product_count"] = str(len(plan))
    latest = max(p["deadline"] for p in plan)

    def answer(d):
        parts = []
        for p in plan:
            if d < today:
                parts.append(p["id"] + ": in the past, ask for another day")
            elif d > p["deadline"]:
                parts.append(p["id"] + ": AFTER its deadline, the latest date is " + spoken(p["deadline"]) + " (" + p["deadline"].isoformat() + "), offer that")
            elif not cal.is_business_day(d):
                nd = cal.next_business_day(d)
                if nd > p["deadline"]:
                    nd = p["deadline"]
                parts.append(p["id"] + ": not a business day, offer " + spoken(nd) + " (" + nd.isoformat() + ")")
            else:
                parts.append(p["id"] + ": accept " + d.isoformat())
        return "; ".join(parts)

    vars["date_answers"] = answer_table(cal, today, (latest - today).days + 10, answer)
except Exception as e:
    vars["debt_statement"] = "I am calling from the collections team about a late payment, but I cannot see your account details right now."
    vars["account_facts"] = "Account facts are not available. Do not state any amount, date or product. Say you do not have the information."
    vars["product_count"] = "0"
    vars["date_answers"] = "Not available."
