        dl_n = int(p.get("days_late") or 0)
        band = RULES["bands"][0] if dl_n <= RULES["bands"][0]["hi"] else RULES["bands"][1]
        dl = cal.add_business_days(today, band["bd"])
        floor = p.get("minimum_payment") if p.get("type") == "credit_card" else p.get("instalment_amount")
        plan.append(dict(id=str(p.get("product_id") or ("p" + str(i + 1))), name=pname(p), past_due=money(p.get("past_due")),
