            elif not cal.is_business_day(d):
                nd = cal.next_business_day(d)
                if nd > p["deadline"]:
                    nd = p["deadline"]
                parts.append(p["id"] + ": not a business day, offer " + spoken(nd) + " (" + nd.isoformat() + ")")
            else:
